package com.gsr.onboarding.dto;

import java.time.LocalDate;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

import com.gsr.onboarding.domain.enums.AccessLevel;
import com.gsr.onboarding.validation.ValidJoiningDate;

import io.swagger.v3.oas.annotations.media.Schema;

/** Employee details submitted by HR. The employee number is generated by the server. */
public record EmployeeRequest(
        @Schema(example = "Priya")
        @NotBlank @Size(max = 100)
        @Pattern(regexp = ValidationPatterns.PERSON_NAME, message = "must contain letters, spaces, apostrophes, dots or hyphens only")
        String firstName,

        @Schema(example = "Sharma")
        @NotBlank @Size(max = 100)
        @Pattern(regexp = ValidationPatterns.PERSON_NAME, message = "must contain letters, spaces, apostrophes, dots or hyphens only")
        String lastName,

        @Schema(example = "priya.sharma@example.com")
        @NotBlank @Size(max = 254) @Email(regexp = ValidationPatterns.EMAIL, message = "must be a valid email address")
        String workEmail,

        @Schema(example = "Backend Engineer")
        @NotBlank @Size(max = 150)
        String jobTitle,

        @Schema(example = "Engineering")
        @NotBlank @Size(max = 100)
        String department,

        @Schema(example = "2026-11-16")
        @NotNull @ValidJoiningDate
        LocalDate joiningDate,

        @Schema(example = "Daniel Okafor")
        @NotBlank @Size(max = 150)
        String reportingManager,

        @Schema(example = "priya-sharma")
        @NotBlank
        @Pattern(regexp = ValidationPatterns.GITHUB_USERNAME, message = "must be a valid GitHub username (1-39 alphanumeric characters or single hyphens)")
        String githubUsername,

        @Schema(example = "acme-corp/payments-service")
        @NotBlank @Size(max = 200)
        @Pattern(regexp = ValidationPatterns.GITHUB_REPOSITORY, message = "must be in the form owner/repository")
        String githubRepository,

        @Schema(example = "WRITE")
        @NotNull
        AccessLevel accessLevel) {
}
